mapper.select:
SELECT username, ip, location, browser, os, login_at AS loginAt
FROM sys_login_log
WHERE login_status = '0'

  AND tenant_id = #{tenantId}

ORDER BY login_at DESC
LIMIT #{limit}

SELECT module_name AS moduleName, business_type AS businessType, operator_name AS operatorName, operation_status AS operationStatus, operation_at AS operationAt FROM sys_operation_log
tenant_id = #{tenantId}
ORDER BY operation_at DESC LIMIT #{limit}
